    "category": "Breads",
    "emoji": "🫓",
    "prepTime": 20,
    "cookTime": 35,
    "difficulty": "Advanced",
    "servings": 4,
    "ingredients": [
      {
        "name": "Wheat flour / required flour",
        "qty": 2,
        "unit": "cups"
      },
      {
        "name": "water",
        "qty": 0.75,
        "unit": "cup"
      },
      {
        "name": "salt",
        "qty": 0.5,
        "unit": "tsp"
      },
      {
        "name": "oil / ghee",
        "qty": 2.0,
        "unit": "tsp"
      }
    ],
    "steps": [
      "Combine flour and salt in a bowl. Add water gradually and knead for 6–8 minutes until a soft, smooth dough forms. For Jowar Roti, use fresh ingredients and keep the pieces uniform.",
      "Cover the dough with a damp cloth and rest for 15–20 minutes so it becomes easier to roll.",
      "Divide into equal balls. Dust lightly with flour and roll each into an even disc; use gentle pressure to avoid tearing.",
      "Heat a tawa or skillet over medium-high heat. Place one rolled disc on the hot surface.",
      "When small bubbles appear, flip and cook the other side. Apply ghee or oil if the style calls for it; puff over a flame only where suitable.",
      "Keep cooked breads covered in a clean cloth and serve warm."
    ],
    "description": "A practical home-style jowar roti recipe with measured ingredients and a clear cooking sequence."
